// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {RewardVault} from "../src/RewardVault.sol";

contract InvMutTest is Test {
    RewardVault c;

    function setUp() public {
        c = new RewardVault();
    }

    function testFuzz_property(address actor, uint256 depositAmount, uint256 newRate) public {
        vm.assume(actor != address(0));
        vm.assume(actor != address(this));
        vm.assume(actor != msg.sender);

        depositAmount = bound(depositAmount, 1, 1000 ether);
        newRate = bound(newRate, 0, 1000);

        vm.deal(actor, depositAmount * 2);

        vm.prank(actor);
        c.deposit{value: depositAmount}();

        vm.prank(c.owner());
        c.setRewardRate(newRate);

        vm.prank(actor);
        c.claim();

        uint256 balanceAfterClaim = c.balance(actor);

        bool withdrawOk;
        vm.prank(actor);
        try c.withdraw() {
            withdrawOk = true;
        } catch {
            withdrawOk = false;
        }

        if (withdrawOk) {
            uint256 balanceAfterWithdraw = c.balance(actor);
            assertTrue(balanceAfterWithdraw == 0);
        } else {
            assertTrue(withdrawOk);
        }
    }
}
